namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed initial data
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was created.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "You have 3 pending tasks.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        });
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            // Simulate new notifications appearing occasionally
            if (Random.Shared.Next(3) == 0)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                    Timestamp = DateTime.UtcNow,
                });
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading...</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var item in Items)
        {
            <li>
                <strong>@item.Timestamp.ToString("HH:mm:ss")</strong> &mdash; @item.Message
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    [PersistentState]
    public List<Notification>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if state wasn't restored from prerender
        Items ??= await NotificationService.GetNotificationsAsync();
        _lastSeenId = Items.Count > 0 ? Items.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender never fires during prerender — safe to start polling
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                var newItems = await NotificationService.GetNotificationsSinceAsync(_lastSeenId);
                if (newItems.Count > 0)
                {
                    Items = newItems.Concat(Items!).ToList();
                    _lastSeenId = Items.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

